 "content": "def transform(grid):
    # Four 4x4 color masks are separated by vertical 3s. Overlay by color precedence.
    panels = [[row[i:i+4] for row in grid] for i in (0, 5, 10, 15)]
    # In overlaps, 9 takes precedence over 4, then 8, then 5.
    priority = {5: 1, 8: 2, 4: 3, 9: 4}
    out = [[0] * 4 for _ in range(4)]
    for r in range(4):
        for c in range(4):
            vals = [p[r][c] for p in panels if p[r][c] != 0]
            if vals:
                out[r][c] = max(vals, key=lambda v: priority.get(v, 0))
    return out
